/// <summary>
/// NDX_MultipleSelect_Customer
/// </summary>
class NDX_MultipleSelect_Customer extends NDX_MultipleSelect
{
    NDXMultipleS_CustTable  nDX_SelectionTmp;        // Vorlagedaten für die Selektion der bereits markierten Datensätze
    CustAccount             accountNum;
    CustTable               custTable;

}

Method.Source:
void closedSelectForm()
{
    FormDataSource  formDatasource;
    int             i, nBis;
    tableId         tableId;
    ;

    nBis = selectForm.dataSourceCount();
    for (i = 1; i <= nBis; i++)
    {
        formDataSource  = selectForm.dataSource(i);
        tableId         = formDataSource.table();
        if (tableId == tablenum(NDXMultipleS_CustTable))
        {
            nDX_SelectionTmp.data(formDatasource.cursor());
            break;
        }
    }
}
